-- store.sql  --  CSL303 'Store' dataset (GENERATED by generate_store.py)
-- Loads on SQLite 3 and PostgreSQL 16.
--   SQLite:   sqlite3 store.db < store.sql
--   Postgres: psql -d store -f store.sql
-- ========================================================================
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS customers;

CREATE TABLE categories (
    cat_id    INTEGER PRIMARY KEY,
    cat_name  TEXT NOT NULL
);

CREATE TABLE customers (
    cust_id    INTEGER PRIMARY KEY,
    name       TEXT NOT NULL,
    city       TEXT,
    country    TEXT,
    join_date  TEXT
);

CREATE TABLE products (
    prod_id    INTEGER PRIMARY KEY,
    prod_name  TEXT NOT NULL,
    cat_id     INTEGER REFERENCES categories (cat_id),
    price      NUMERIC CHECK (price >= 0),
    stock      INTEGER CHECK (stock >= 0)
);

CREATE TABLE orders (
    order_id    INTEGER PRIMARY KEY,
    cust_id     INTEGER REFERENCES customers (cust_id),
    order_date  TEXT NOT NULL,
    status      TEXT
);

CREATE TABLE order_items (
    order_id    INTEGER REFERENCES orders (order_id),
    prod_id     INTEGER REFERENCES products (prod_id),
    quantity    INTEGER CHECK (quantity > 0),
    unit_price  NUMERIC CHECK (unit_price >= 0),
    PRIMARY KEY (order_id, prod_id)
);






-- End of store.sql
